 73	<main>
 74	  <h1>Todos</h1>
 75	  <form id="todo-form" autocomplete="off">
 76	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
 77	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
 78	    <select data-testid="todo-priority" aria-label="Priority">
 79	      <option value="low">Low</option>
 80	      <option value="med" selected>Med</option>
 81	      <option value="high">High</option>
 82	    </select>
 83	    <button data-testid="todo-add" class="add" type="submit">Add</button>
 84	  </form>
 85	  <div class="filters" role="group" aria-label="Filter todos">
 86	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
 87	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
 88	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
 89	  </div>
 90	  <input data-testid="search-input" class="search" type="search" placeholder="Search todos" aria-label="Search todos">
 91	  <ul data-testid="todo-list"></ul>
 92	  <p class="empty" hidden>No todos yet.</p>
 93	</main>
 94	<script>
 95	(function () {
 96	  var STORAGE_KEY = 'todos';
 97	  var form = document.getElementById('todo-form');
 98	  var input = document.querySelector('[data-testid="todo-input"]');
 99	  var dueInput = document.querySelector('[data-testid="todo-due"]');
100	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
101	  var list = document.querySelector('[data-testid="todo-list"]');
102	  var empty = document.querySelector('.empty');
103	  var filterButtons = document.querySelectorAll('[data-filter]');
104	  var searchInput = document.querySelector('[data-testid="search-input"]');
105	  var filter = 'all';
106	  var query = '';
107	  var editingId = null;
108	
109	  function load() {
110	    try {
111	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
112	      if (!Array.isArray(data)) return [];
113	      return data.filter(function (t) {
114	        return t && typeof t.id === 'string' && typeof t.text === 'string';
115	      }).map(function (t) {
116	        t.completed = t.completed === true;
117	        t.due = isDateString(t.due) ? t.due : null;
118	        t.priority = isPriority(t.priority) ? t.priority : DEFAULT_PRIORITY;
119	        return t;
120	      });
121	    } catch (e) {
122	      return [];
123	    }
124	  }
125	
126	  function save() {
127	    try {
128	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
129	    } catch (e) {
130	      // Storage unavailable or full; keep working in memory.
131	    }
132	  }
133	
134	  var PRIORITIES = ['low', 'med', 'high'];
135	  var DEFAULT_PRIORITY = 'med';
136	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
137	
138	  function isPriority(value) {
139	    return PRIORITIES.indexOf(value) !== -1;
140	  }
141	
142	  function makeId() {
143	    if (window.crypto && typeof crypto.randomUUID === 'function') {
144	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
145	    }
146	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
147	  }
148	
149	  // Due date rule (project decision): `due` is a plain 'YYYY-MM-DD' string
150	  // holding a LOCAL calendar date, or null. Never parse it with `new Date(str)`
151	  // (that reads it as UTC midnight). Overdue means due < today's local date,
152	  // compared as strings; a todo due today is never overdue.
153	  function isDateString(value) {
154	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
155	  }
156	
157	  function pad(n) {
158	    return (n < 10 ? '0' : '') + n;
159	  }
160	
161	  function todayLocal() {
162	    var d = new Date();
163	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
164	  }
165	
166	  function isOverdue(todo, today) {
167	    return todo.due !== null && todo.due < today;
168	  }
169	
170	  function formatDue(due) {
171	    var parts = due.split('-');
172	    var local = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
173	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
174	  }
175	
176	  // Ordering rule (project decision): completed todos always sit below all
177	  // active todos. Within each group, higher priority comes first
178	  // (high, med, low); equal priority keeps insertion order, oldest first.
179	  // `todos` is stored in insertion order and never reordered.
180	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
181	
182	  function ordered() {
183	    return todos.map(function (t, i) { return { todo: t, index: i }; })
184	      .sort(function (a, b) {
185	        return (a.todo.completed - b.todo.completed) ||
186	          (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) ||
187	          (a.index - b.index);
188	      })
189	      .map(function (entry) { return entry.todo; });
190	  }
191	
192	  // Search combines with the status filter: a todo is shown only if it passes
193	  // both. Matching is a case-insensitive substring test on the todo text.
194	  function visible(todo) {
195	    if (filter === 'active' && todo.completed) return false;
196	    if (filter === 'completed' && !todo.completed) return false;
197	    return query === '' || todo.text.toLowerCase().indexOf(query) !== -1;
198	  }
199	
200	  function render() {
201	    list.textContent = '';
202	    var shown = ordered().filter(visible);
203	    var today = todayLocal();
204	    renderedDay = today;
205	    shown.forEach(function (todo) {
206	      var li = document.createElement('li');
207	      li.setAttribute('data-testid', 'todo-item');
208	      li.setAttribute('data-id', todo.id);
209	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
210	      li.setAttribute('data-priority', todo.priority);
211	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
212	
213	      var box = document.createElement('input');
214	      box.type = 'checkbox';
215	      box.className = 'toggle';
216	      box.setAttribute('data-testid', 'todo-toggle');
217	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
218	      box.checked = todo.completed;
219	      box.addEventListener('change', function () { toggle(todo.id); });
220	
221	      var span = document.createElement('span');
222	      span.className = 'text';
223	      span.setAttribute('data-testid', 'todo-text');
224	      span.textContent = todo.text;
225	      span.addEventListener('dblclick', function () { startEdit(todo.id, span); });
226	
227	      var del = document.createElement('button');
228	      del.type = 'button';
229	      del.className = 'delete';
230	      del.setAttribute('data-testid', 'todo-delete');
231	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
232	      del.textContent = 'Delete';
233	      del.addEventListener('click', function () { remove(todo.id); });
234	
235	      li.appendChild(box);
236	      var priority = document.createElement('span');
237	      priority.className = 'priority';
238	      priority.textContent = PRIORITY_LABELS[todo.priority];
239	
240	      li.appendChild(span);
241	      li.appendChild(priority);
242	      if (todo.due) {
243	        var due = document.createElement('time');
244	        due.className = 'due';
245	        due.setAttribute('data-testid', 'todo-due-date');
246	        due.setAttribute('datetime', todo.due);
247	        due.textContent = (isOverdue(todo, today) ? 'Overdue: ' : 'Due ') + formatDue(todo.due);
248	        li.appendChild(due);
249	      }
250	      li.appendChild(del);
251	      list.appendChild(li);
252	    });
253	    if (todos.length === 0) {
254	      empty.textContent = 'No todos yet.';
255	    } else if (query !== '') {
256	      empty.textContent = 'No todos match your search.';
257	    } else if (filter === 'active') {
258	      empty.textContent = 'No active todos.';
259	    } else {
260	      empty.textContent = 'No completed todos.';
261	    }
262	    empty.hidden = shown.length > 0;
263	
264	    filterButtons.forEach(function (btn) {
265	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
266	    });
267	  }
268	
269	  function add(text, due, priority) {
270	    text = text.trim();
271	    if (!text) return false;
272	    todos.push({
273	      id: makeId(),
274	      text: text,
275	      completed: false,
276	      due: isDateString(due) ? due : null,
277	      priority: isPriority(priority) ? priority : DEFAULT_PRIORITY,
278	      createdAt: Date.now()
279	    });
280	    save();
281	    render();
282	    return true;
283	  }
284	
285	  function remove(id) {
286	    todos = todos.filter(function (t) { return t.id !== id; });
287	    save();
288	    render();
289	  }
290	
291	  function toggle(id) {
292	    todos.forEach(function (t) {
293	      if (t.id === id) t.completed = !t.completed;
294	    });
295	    save();
296	    render();
297	  }
298	
299	  function find(id) {
300	    for (var i = 0; i < todos.length; i++) {
301	      if (todos[i].id === id) return todos[i];
302	    }
303	    return null;
304	  }
305	
306	  // Inline editing: double-click swaps the text for an input. Enter or blur
307	  // commits, Escape cancels. An empty result cancels rather than deletes.
308	  // On commit the row is patched in place instead of re-rendered, so a click
309	  // that caused the blur (e.g. on another row's checkbox) still lands.
310	  function startEdit(id, span) {
311	    var todo = find(id);
312	    if (!todo || editingId !== null) return;
313	    editingId = id;
314	    var li = span.parentNode;
315	    var field = document.createElement('input');
316	    field.type = 'text';
317	    field.className = 'edit';
318	    field.setAttribute('data-testid', 'todo-edit-input');
319	    field.setAttribute('aria-label', 'Edit todo');
320	    field.value = todo.text;
321	    var finished = false;
322	
323	    function finish(commit) {
324	      if (finished) return;
325	      finished = true;
326	      editingId = null;
327	      var text = field.value.trim();
328	      if (commit && text && text !== todo.text) {
329	        todo.text = text;
330	        save();
331	        if (!visible(todo)) {
332	          render();
333	          return;
334	        }
335	        span.textContent = text;
336	        li.querySelector('[data-testid="todo-toggle"]').setAttribute('aria-label', 'Mark "' + text + '" complete');
337	        li.querySelector('[data-testid="todo-delete"]').setAttribute('aria-label', 'Delete "' + text + '"');
338	      }
339	      if (field.parentNode) li.replaceChild(span, field);
340	      refreshIfNewDay();
341	    }
342	
343	    field.addEventListener('keydown', function (e) {
344	      if (e.key === 'Enter') {
345	        e.preventDefault();
346	        finish(true);
347	      } else if (e.key === 'Escape') {
348	        e.preventDefault();
349	        finish(false);
350	      }
351	    });
352	    field.addEventListener('blur', function () { finish(true); });
353	
354	    li.replaceChild(field, span);
355	    field.focus();
356	    field.setSelectionRange(field.value.length, field.value.length);
357	  }
358	
359	  var todos = load();
360	  var renderedDay = null;
361	
362	  // Re-render when the local date rolls over so overdue flags stay current.
363	  function refreshIfNewDay() {
364	    // Don't re-render under an open edit; finishing the edit calls this again.
365	    if (editingId === null && todayLocal() !== renderedDay) render();
366	  }
367	  setInterval(refreshIfNewDay, 60 * 1000);
368	  document.addEventListener('visibilitychange', function () {
369	    if (!document.hidden) refreshIfNewDay();
370	  });
371	
372	  filterButtons.forEach(function (btn) {
373	    btn.addEventListener('click', function () {
374	      filter = btn.getAttribute('data-filter');
375	      render();
376	    });
377	  });
378	
379	  searchInput.addEventListener('input', function () {
380	    query = searchInput.value.trim().toLowerCase();
381	    render();
382	  });
383	
384	  form.addEventListener('submit', function (e) {
385	    e.preventDefault();
386	    if (add(input.value, dueInput.value, priorityInput.value)) {
387	      dueInput.value = '';
388	      priorityInput.value = DEFAULT_PRIORITY;
389	    }
390	    input.value = '';
391	    input.focus();
392	  });
393	
394	  render();
395	})();
396	</script>
397	</body>
398	</html>

